function methods(){return[paragraph('OUR EVIDENCE STANDARD','eyebrow'),el('h1',{},'Investigate first.',el('br'),'Prove what can be proven.'),el('div',{class:'prose'},paragraph('HalifaxData is a public watchdog, not a government publicity dashboard or an automated accusation system. Our first task is to trace spending and investigate unanswered questions.'),el('h2',{},'How a question becomes a finding'),list(['Register a source and check access, terms, scope and privacy.','Preserve source versions, identifiers, retrieval dates and transformations.','Normalize amounts without erasing currency, tax, timing or accounting definitions.','Connect records only with explicit identifiers or documented reviewed evidence.','Run reproducible checks and record competing explanations.','Review consequential allegations before publication. An automated flag is never a verdict.']),el('h2',{},'What is available now'),paragraph('The fresh foundation provides a source register, financial record search, a neutral budget comparison and a reviewed unresolved municipal reporting question. Unreviewed investigative leads are not included in public bundles. It does not yet provide a complete payment ledger, vendor ownership graph, district investigation system or comprehensive government coverage.'),el('h2',{},'The full mission stays in scope'),el('ul',{class:'scope-list'},...[['Government decisions','Link approvals, motion versions and recorded votes to financial consequences.'],['All 16 Halifax districts','Versioned boundaries, documented local issues, projects and representative actions. No automatic blame.'],['Procurement and delivery','Follow awards, amendments, payments, contractors and completion evidence.'],['Provincial public services','Investigate healthcare, infrastructure, housing, education and measurable results.'],['Relationships and accountability','Evidence-backed entity relationships, audit follow-ups and conflicts where legally public.'],['Better government, later','Validated spending alternatives and policy simulations after the investigative foundation is reliable.']].map(([title,text])=>el('li',{},el('strong',{},title),paragraph(text)))),el('h2',{},'Corrections and responses'),paragraph('New evidence can change a finding. Corrections must retain the prior claim, the new source, the reason and the review date. Official responses must be attributed and assessed, not silently substituted. This release has no public submission form or direct outreach automation.'),el('h2',{},'Privacy and independence'),paragraph('We do not publish patient identities, complainant details or unreviewed personal information. We do not rank politicians or infer wrongdoing from names, locations or timing alone. The same evidentiary standard applies across parties and institutions.'),el('h2',{},'Data limitations'),paragraph('A catalogue entry is not an integration. A primary-text review without a retained binary is labelled as such. A successful refresh does not make older source facts current. Missing evidence is an open research task, not evidence of absence.'),link('Inspect every source and its status →','#/sources','button secondary'))];}
